query:
SELECT 'inad_all' as src, COUNT(*) as cnt FROM accounts_receivable 
WHERE estado = 'EMITIDO' AND vencimentoData <= NOW();

SELECT 'inad_valid' as src, COUNT(*) as cnt FROM accounts_receivable 
WHERE estado = 'EMITIDO' AND vencimentoData <= NOW() 
AND tipo IN ('TITULO', 'RECEITA', 'ADIANTAMENTO');

SELECT 'planilha' as src, COUNT(*) as cnt FROM cobranca_planilha;

SELECT tipo, COUNT(*) as cnt FROM accounts_receivable 
WHERE estado = 'EMITIDO' AND vencimentoData <= NOW()
GROUP BY tipo ORDER BY cnt DESC;

